{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-showcase.json
    Features as cards under a centered heading. Axes: item (picture: a picture on top, then the title, the text and a read link; panel: a muted panel with a large glyph on top, then the title and the text), cols (3, 4), tone.
    Props (p): id, title, lead, features, more, item, cols, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_features = ($p['features'] ?? null)}
{var $v_more = ($p['more'] ?? null)}
{var $v_item = ($p['item'] ?? 'picture')}
{var $v_cols = ($p['cols'] ?? '3')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {capture $c_7}
    {foreach ui_l($v_features) as $v_f}
      {capture $c_6}
        {if ui_t(ui_eq($v_item, 'picture'))}
          {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_f, ['title'])]])|noescape}
        {else}
          {capture $c_1}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_f, ['icon'])), 'Size' => 32]])|noescape}
          {/capture}
          {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex aspect-video items-center justify-center rounded bg-muted text-foreground', 'Attrs' => ui_attrs(['data-testid', 'showcase-panel'])], 'children' => $c_1])|noescape}
        {/if}
        {capture $c_5}
          {capture $c_2}
            {=ui_text(ui_get($v_f, ['title']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'semibold'], 'children' => $c_2])|noescape}
          {capture $c_3}
            {=ui_text(ui_get($v_f, ['text']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
          {if ui_t(ui_eq($v_item, 'picture'))}
            {capture $c_4}
              {=ui_text($v_more)}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'arrow-right', 'Size' => 16]])|noescape}
            {/capture}
            {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/', 'Size' => 'sm', 'Class' => 'mt-auto pt-2', 'Attrs' => ui_attrs(['data-testid', 'read'])], 'children' => $c_4])|noescape}
          {/if}
        {/capture}
        {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => 'flex flex-1 flex-col gap-2'], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Class' => 'h-full gap-4 overflow-hidden', 'Attrs' => ui_attrs(['data-testid', 'showcase-card'])], 'children' => $c_6])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_cols, '4')) ? 'grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-3'))], 'children' => $c_7])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_8])|noescape}
